INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(38411, 'Isaiah 10:9', 'Isaiah', 10, 9, 'ما د کرکمیش، کلنو او همدارنګه د ارفاد او حمات ښارونه فتح کړي دي. دمشق او سامره مې هم فتح کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_9.mp3', '', 1761754199, 1761754199),
(38412, 'Isaiah 10:10', 'Isaiah', 10, 10, 'ما خپل لاس د هغو پاچاهیو د فتح کولو دپاره اوچت کړی چې د بتانو عبادت کوي. هغه پاچاهیو د اورشلیم او سامرې څخه زیات بتان درلودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_10.mp3', '', 1761754199, 1761754199),
(38413, 'Isaiah 10:11', 'Isaiah', 10, 11, 'ما سامره او د هغې ټول بتان له منځه یووړل، خو زه به اورشلیم او د هغه مجسمې چې عبادت ورته کیږي، هم له منځه یوسم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_11.mp3', '', 1761754199, 1761754199),
(38414, 'Isaiah 10:12', 'Isaiah', 10, 12, 'کله چې څښتن خپل کارونه د صهیون په غره او اورشلیم کې پای ته ورسوي، نو هغه وخت به د اشور پاچا ته د هغه د ټولو لافو او ټول غرور په خاطر سزا ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_12.mp3', '', 1761754199, 1761754199),
(38415, 'Isaiah 10:13', 'Isaiah', 10, 13, 'د اشور پاچا لاپې وهي او وایي: «زه د خپلو مټو په زور، پوهې او حکمت سره په جګړو کې بریالی شوم. د هېوادونو ترمنځ مې سرحدونه له منځه یووړل او د هغوی خزانې مې لوټ کړې. لکه د قوي غویي په شان مې د هغو ځایونو پاچاهان د تختونو څخه وغورځول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_13.mp3', '', 1761754199, 1761754199),
(38416, 'Isaiah 10:14', 'Isaiah', 10, 14, 'د نړۍ هېوادونه زما دپاره د مرغۍ د ځالې په شان وو. ما د هغوی خزانې داسې په اسانۍ سره خالي کړې لکه څوک چې د ځالې نه پاتې شوې هګۍ راټولوي. نه یو وزر ورپېده چې ما ووېروي او نه کومه مښوکه خلاصه شوه چې په ما باندې وچوغیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_14.mp3', '', 1761754199, 1761754199),
(38417, 'Isaiah 10:15', 'Isaiah', 10, 15, 'خو څښتن وایي: «ایا تبر دا دعوه کولای شي چې دی د هغه سړي څخه چې ورڅخه کار اخلي ډېر لوی دی؟ ایا اره د اره کوونکي نه مهمه ده؟ انسان لرګی راپورته کوي، نه لرګی انسان.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_15.mp3', '', 1761754199, 1761754199),
(38418, 'Isaiah 10:16', 'Isaiah', 10, 16, 'نو مطلق قادر څښتن به یو وژونکی مرض راولېږي چې د اشور جنګیالیو ته، چې تکړه دي، سزا ورکړي. د هغوی لویي او شتمني به د اور لمبې وسوځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_16.mp3', '', 1761754199, 1761754199),
(38419, 'Isaiah 10:17', 'Isaiah', 10, 17, 'د اسراییلو رڼا به په سوځوونکي اور بدله شي. د اسراییلو د سپېڅلي خدای د غوسې لمبې به په یوه ورځ د اشوریانو هرڅه لکه د اغزیو او کرکڼو په شان وسوځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_17.mp3', '', 1761754199, 1761754199),
(38420, 'Isaiah 10:18', 'Isaiah', 10, 18, 'شنه شنه ځنګلونه او حاصلخېزې ځمکې به داسې بیخي له منځه لاړې شي لکه څنګه چې یوه وژونکې ناروغي انسان له منځه وړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_18.mp3', '', 1761754199, 1761754199),
(38421, 'Isaiah 10:19', 'Isaiah', 10, 19, 'په ځنګلونو کې به دومره لږې ونې پاتې شي چې حتی یو ماشوم به هم وکولای شي چې هغه وشمېري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_19.mp3', '', 1761754199, 1761754199),
(38422, 'Isaiah 10:20', 'Isaiah', 10, 20, 'داسې ورځ راروانه ده چې د اسراییلو هغه خلک چې ژوندي پاتې شوي دي، یعنې د یعقوب اولاده چې ژغورل شوې ده، هغوی به نور په هغه هېواد باندې چې په دوی یې ظلم کړی دی، تکیه ونه کړي. هغوی به یوازې په څښتن یعنې د اسراییلو په سپېڅلي خدای باندې تکیه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_20.mp3', '', 1761754199, 1761754199),
(38423, 'Isaiah 10:21', 'Isaiah', 10, 21, 'د یعقوب پاتې شوې اولاده به مطلق خدای ته رجوع وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_21.mp3', '', 1761754199, 1761754199),
(38424, 'Isaiah 10:22', 'Isaiah', 10, 22, 'که څه هم اسراییلیان اوس د بحیرې د شګو په شان زیات دي خو یوه کوچنۍ پاتې شوې برخه به راستنه شي. په دې خلکو باندې د تباهي پرېکړه شوې ده او هغوی د دې لایق دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_22.mp3', '', 1761754199, 1761754199),
(38425, 'Isaiah 10:23', 'Isaiah', 10, 23, 'هو، لکه څنګه چې مطلق قادر څښتن خدای پرېکړه کړې ده، هغه به ټول هېواد له منځه یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_23.mp3', '', 1761754199, 1761754199),
(38426, 'Isaiah 10:24', 'Isaiah', 10, 24, 'مطلق قادر څښتن خدای داسې وایي: «ای زما قومه چې په صهیون کې اوسېږئ، له اشوریانو مه وېرېږئ، که څه هم هغوی په تاسو باندې داسې ظلم کوي لکه څنګه چې مصریانو درسره کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_24.mp3', '', 1761754199, 1761754199),
(38427, 'Isaiah 10:25', 'Isaiah', 10, 25, 'ځکه زما قهر به ډېر لږ وخت وروسته پای ته ورسیږي او بیا به زه اشوریانو ته په قهر شم او هغوی به له منځه یوسم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_25.mp3', '', 1761754199, 1761754199),
(38428, 'Isaiah 10:26', 'Isaiah', 10, 26, 'زه مطلق قادر څښتن به هغوی په خپله قمچینه داسې ووهم لکه څنګه مې چې د مدیان خلک د غراب د ګټ تر څنګ وهلي وو. زه به اشوریانو ته هغه شان سزا ورکړم لکه څنګه چې مې د مصریانو لښکر په بحیره کې ډوب کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_26.mp3', '', 1761754199, 1761754199),
(38429, 'Isaiah 10:27', 'Isaiah', 10, 27, 'کله چې هغه ورځ راشي، نو د اشوریانو پېټی به ستاسو له اوږو او د اسارت جغ به ستاسو له غاړې څخه لېرې شي. جغ به د سوکالۍ له امله مات شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_27.mp3', '', 1761754199, 1761754199),
(38430, 'Isaiah 10:28', 'Isaiah', 10, 28, 'د دښمن لښکر د عای ښار ته رسېدلی دی! هغوی د مجرون نه تېر شوي دي او خپل سامان یې په مخماس کې پریښی دی!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_28.mp3', '', 1761754199, 1761754199),
(38431, 'Isaiah 10:29', 'Isaiah', 10, 29, 'هغوی د کنډو څخه تېر شوي دي او شپه په جبع کې تېروي. د رامې د ښار خلک له وېرې رپیږي او د جبعې یعنې د شاوول پاچا د ښار خلک تښتېدلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_29.mp3', '', 1761754199, 1761754199),
(38432, 'Isaiah 10:30', 'Isaiah', 10, 30, 'ای د جلیم خلکو، چیغې ووهئ! ای د لیشې خلکو، غوږ ونیسئ! ای د عناتوت بې چاره خلکو!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_30.mp3', '', 1761754199, 1761754199),
(38433, 'Isaiah 10:31', 'Isaiah', 10, 31, 'د مدمینې خلک تښتي او د جیبیم خلک د پناه دپاره منډې وهي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_31.mp3', '', 1761754199, 1761754199),
(38434, 'Isaiah 10:32', 'Isaiah', 10, 32, 'دښمن به نن د نوب په ښار کې وي. هغوی خپل سوک د اورشلیم خواته چې د صهیون په غره کې دی د اخطار په توګه خوځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_32.mp3', '', 1761754199, 1761754199),
(38435, 'Isaiah 10:33', 'Isaiah', 10, 33, 'ګورئ، مطلق قادر څښتن به هغوی داسې راوغورځوي لکه څنګه چې د لوړو ونو څانګې په درب رالویږي. د ونو په شان به د هغوی لوی لوی خلک راوغورځوي او هغوی به خوار او ذلیل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_33.mp3', '', 1761754199, 1761754199),
(38436, 'Isaiah 10:34', 'Isaiah', 10, 34, 'څښتن به هغوی داسې راوغورځوي لکه څنګه چې ونې د ځنګل په منځ کې په تبر رالویږي، لکه څنګه چې د لبنان ښایسته او جګې ونې راغورځیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_34.mp3', '', 1761754199, 1761754199),
(38437, 'Isaiah 27:1', 'Isaiah', 27, 1, 'په هغه ورځ به څښتن په خپلې تېرې، وژونکې او غټې تورې سره بحري بلا ته یعنې هغه تښتېدونکی مار چې تاویږي او راتاویږي، سزا ورکړي او هغه ښامار به ووژني چې په بحیره کې اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah27_verse_1.mp3', '', 1761754199, 1761754199),
(38438, 'Isaiah 27:2', 'Isaiah', 27, 2, 'په هغه ورځ به څښتن ووایي: «د یو زړه وړونکي د انګورو باغ په اړه سندره ووایئ:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah27_verse_2.mp3', '', 1761754199, 1761754199),
(38439, 'Isaiah 27:3', 'Isaiah', 27, 3, 'زه څښتن یمه ساتونکی د دې باغ او هر وخت ورته اوبه ورکوم شپه او ورځ ترې زه ساتنه کوم چې څوک ونه رسوي زیان ورته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah27_verse_3.mp3', '', 1761754199, 1761754199),
(38440, 'Isaiah 27:4', 'Isaiah', 27, 4, 'زه د انګورو په باغ په قهر نه یمه نور خو که په کې ولیدل شي اغزي او کرکڼې وبه جنګېږم د هغو په وړاندې او ټول به وسوځوم زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah27_verse_4.mp3', '', 1761754199, 1761754199),
(38441, 'Isaiah 27:5', 'Isaiah', 27, 5, 'خو که وغواړي دښمنان زما د قوم چې راوړي ماته پناه او غوښتنه وکړي له ما د روغې جوړې پرېږدئ چې وکړي روغه جوړه دوی زما سره.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah27_verse_5.mp3', '', 1761754199, 1761754199),
(38442, 'Isaiah 27:6', 'Isaiah', 27, 6, 'هغه وخت به راشي چې د اسراییلو قوم یعنې د یعقوب اولاده لکه د ونې په شان ریښې وکړي، غوټۍ ونیسي او ګلان وغوړوي او ټوله نړۍ له مېوې ډکه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah27_verse_6.mp3', '', 1761754199, 1761754199),
(38443, 'Isaiah 27:7', 'Isaiah', 27, 7, 'څښتن اسراییلیانو ته دومره سزا نه ده ورکړې لکه د هغوی دښمنانو ته چې یې ورکړې ده. د اسراییلو خلک یې د هغوی په اندازه نه دي وژلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah27_verse_7.mp3', '', 1761754199, 1761754199),
(38444, 'Isaiah 27:8', 'Isaiah', 27, 8, 'څښتن د اسراییلو خلکو ته سزا ورکړه او هغوی یې جلاوطنه کړل. هغوی یې د ختیځ له خوا د یو تند باد سره لېرې یووړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah27_verse_8.mp3', '', 1761754199, 1761754199),
(38445, 'Isaiah 27:9', 'Isaiah', 27, 9, 'خو د اسراییلو ګناهونه به یوازې هغه وخت وبخښل شي او پای ته به ورسیږي کله چې بتانو ته د قربانۍ د ځایونو تیږې لکه د تباشیر په شان ټوټې ټوټې شي او همدارنګه بتانو ته د خوشبویۍ د سوځولو د قربانۍ ځایونو او د اشیره د بتانو نښې نښانې پاتې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah27_verse_9.mp3', '', 1761754199, 1761754199),
(38446, 'Isaiah 27:10', 'Isaiah', 27, 10, 'ټینګ ښارونه پرېښودل شوي دي او د دښتې په شان څوک په کې نه اوسیږي. هغه د څارویو څړځای جوړ شوی دی چې په کې ارام وي او د څانګو پاڼې وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah27_verse_10.mp3', '', 1761754199, 1761754199),
(38447, 'Isaiah 27:11', 'Isaiah', 27, 11, 'د ونو څانګې وچې شوې، ښځې یې ماتوي او د سوځولو دپاره یې وړي. څښتن چې د هغوی خالق دی، په دې قوم زړه نه سوځوي او رحم نه کوي، ځکه چې هغوی پوهه نه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah27_verse_11.mp3', '', 1761754199, 1761754199),
(38448, 'Isaiah 27:12', 'Isaiah', 27, 12, 'په هغه ورځ به څښتن لکه څوک چې غنم له بوسو جدا کوي، همداسې به د اسراییلو خلک د فرات د سیند نه نیولې د مصر تر پولې پورې یو یو کس راغونډ کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah27_verse_12.mp3', '', 1761754199, 1761754199),
(38449, 'Isaiah 27:13', 'Isaiah', 27, 13, 'په هغه ورځ به لوی سرنی ووهل شي او هغه ټول اسراییلیان چې د اشور او د مصر په هېوادونو کې جلاوطنه دي، هغوی به بېرته خپل هېواد ته راستانه شي او د څښتن عبادت به د هغه په سپېڅلي غره باندې چې په اورشلیم کې دی، وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah27_verse_13.mp3', '', 1761754199, 1761754199),
(38450, 'Ecclesiastes 8:1', 'Ecclesiastes', 8, 1, 'د حکمت خاوند څوک دی؟ څوک د یو موضوع په څرګندولو پوهیږي؟ د یو انسان حکمت د هغه څېره روښانوي او د هغه سخت صورت نرموي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes8_verse_1.mp3', '', 1761754199, 1761754199),
(38451, 'Ecclesiastes 8:2', 'Ecclesiastes', 8, 2, 'زما نصیحت دا دی چې د پاچا د حکم څخه اطاعت وکړه، ځکه خدای له هغه سره وعده کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes8_verse_2.mp3', '', 1761754199, 1761754199),
(38452, 'Ecclesiastes 8:3', 'Ecclesiastes', 8, 3, 'نو د هغه د حضور څخه په تللو کې بیړه مه کوه او د هغو خلکو سره مه یوځای کېږه چې د هغه په ضد دسیسې جوړوي، ځکه پاچا هر هغه څه کولای شي چې زړه یې وغواړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes8_verse_3.mp3', '', 1761754199, 1761754199),
(38453, 'Ecclesiastes 8:4', 'Ecclesiastes', 8, 4, 'په حقیقت کې، د پاچا حکم تر هرڅه لوړ دی او هېڅوک هغه ته نه شي ویلی چې ته څه کوې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes8_verse_4.mp3', '', 1761754199, 1761754199),
(38454, 'Ecclesiastes 8:5', 'Ecclesiastes', 8, 5, 'څوک چې د هغه حکم ومني نو هغه به په هېڅ یوه دسیسه کې برخه وانخلي، او هوښیار سړی په مناسب وخت او سم قضاوت باندې پوهیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes8_verse_5.mp3', '', 1761754199, 1761754199),
(38455, 'Ecclesiastes 8:6', 'Ecclesiastes', 8, 6, 'که څه هم انسان ډېرې بدبختۍ ګالي خو د هر مقصد دپاره مناسب وخت او سم قضاوت ټاکل شوی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes8_verse_6.mp3', '', 1761754199, 1761754199),
(38456, 'Ecclesiastes 8:7', 'Ecclesiastes', 8, 7, 'انسان نه پوهیږي چې راتلونکی به څه ډول وي، نو څوک کولای شي بل چاته ووایي چې څه به پېښیږي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes8_verse_7.mp3', '', 1761754199, 1761754199),
(38457, 'Ecclesiastes 8:8', 'Ecclesiastes', 8, 8, 'لکه څنګه چې هېڅوک د ژوند د ساه د ساتلو اختیار نه لري همدا شان هېڅوک د خپل مرګ د ورځې اختیار هم نه لري لکه څنګه چې هېڅوک د جګړې په وخت د رخصتۍ اجازه نه لري همدا شان هېڅوک په خپلو بدکاریو ځان نه شي ژغورلی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes8_verse_8.mp3', '', 1761754199, 1761754199),
(38458, 'Ecclesiastes 8:9', 'Ecclesiastes', 8, 9, 'کله چې ما په خپل زړه کې هر هغه څه ته چې د اسمان لاندې تر‌سره کیږي فکر وکړ، نو ومې لیدل چې کله کله یو انسان په بل انسان باندې واک او اختیار لري او هغه ته زیان رسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes8_verse_9.mp3', '', 1761754199, 1761754199),
(38459, 'Ecclesiastes 8:10', 'Ecclesiastes', 8, 10, 'نو بیا ما ولیدل چې د بدکارانو مړي ښخ شوي وو. هماغه بدکاران چې سپېڅلي ځای ته تلل راتلل، په هغه ښار کې چې هغوی بد کارونه تر‌سره کړي وو، د خلکو له خوا ستایل کېدل. نو دا حالت هم لوګی او پوکی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes8_verse_10.mp3', '', 1761754199, 1761754199),
(38460, 'Ecclesiastes 8:11', 'Ecclesiastes', 8, 11, 'کله چې بدکارانو ته د هغو د بدو کارونو په خاطر سمدلاسه د سزا پرېکړه ونه شي، نو د انسانانو زړه د بدکارۍ په لور هڅول کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes8_verse_11.mp3', '', 1761754199, 1761754199),
(38461, 'Ecclesiastes 8:12', 'Ecclesiastes', 8, 12, 'که څه هم یو ګناهکار ښایي سل وارې بد کارونه وکړي او لا هم اوږد ژوند ولري، بیاهم زه پوهېږم چې دا به له خدای څخه وېرېدونکو خلکو سره ښه په مخ ځي، ځکه چې دوی له هغه څخه په وېره کې ژوند کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes8_verse_12.mp3', '', 1761754199, 1761754199),
(38462, 'Ecclesiastes 8:13', 'Ecclesiastes', 8, 13, 'خو له بدکار انسان سره به دا ښه په مخ نه ځي، او د هغه د ژوند ورځې به د سیوري په څېر اوږدې نه وي، ځکه چې هغه له خدای څخه په وېره کې ژوند نه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes8_verse_13.mp3', '', 1761754199, 1761754199),
(38463, 'Ecclesiastes 8:14', 'Ecclesiastes', 8, 14, 'دلته د لوګي او پوکي څخه ډک حالت د ځمکې په مخ موجود دی: ځینې نېکان هغه څه تر‌لاسه کوي چې بدکاران د هغه مستحق دي خو بیا ځینې بدکاران هغه څه تر‌لاسه کوي چې نېکان د هغه مستحق دي نو له ځان سره مې وویل: «دا حالت هم لوګی او پوکی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes8_verse_14.mp3', '', 1761754199, 1761754199),
(38464, 'Ecclesiastes 8:15', 'Ecclesiastes', 8, 15, 'نو زه له ژوند نه د خوند اخیستلو سپارښتنه کوم، ځکه چې د اسمان لاندې له دې نه بل ښه کار نشته چې انسان وخوري، وڅښي او خوشحاله اوسي. نو دا خوشحالي به د هغه د ژوند په موده کې او د هغه په زیار او زحمت کې له هغه سره مل وي چې خدای هغه ته د اسمان لاندې ورکړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes8_verse_15.mp3', '', 1761754199, 1761754199),
(38465, 'Ecclesiastes 8:16', 'Ecclesiastes', 8, 16, 'کله چې ما د حکمت د پېژندلو هڅه وکړه ترڅو د ځمکې په مخ چې هر کار تر‌سره کیږي وڅېړم، که څه هم دا کار د یو کس د شپې یا د ورځې له خوب کولو څخه مخنیوی کوي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes8_verse_16.mp3', '', 1761754199, 1761754199),
(38466, 'Ecclesiastes 8:17', 'Ecclesiastes', 8, 17, 'نو بیا ما ټول هغه کارونه ولیدل چې خدای تر‌سره کړي وو. په حقیقت کې، هېڅوک دا پټ راز نه شي پیدا کولای چې د اسمان لاندې خدای کوم کارونه تر‌سره کړي دي. انسان د خپل ټول زیار او زحمت سره سره چې د هغه په لټولو کې یې وباسي، لا هم نه شي کولای دا راز پیدا کړي. حتی که یو پوه او هوښیار سړی دعوه وکړي چې زه د خدای په کارونو پوهېږم، خو په حقیقت کې، هغه به هېڅکله دا راز پیدا نه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes8_verse_17.mp3', '', 1761754199, 1761754199),
(38467, 'Songofsongs 4:1', 'Songofsongs', 4, 1, 'اے محبوبې، تۀ څومره ښائسته ينه. تۀ څومره نازنينه ينه. د نقاب نه شاته ستا سترګې ګوګوشتکې دينه. ستا زلفى وَل وَل لکه د چېلو د رمو په شان دينه، چې د جِلعاد د غرۀ نه لاندې راکوزيږينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs4_verse_1.mp3', '', 1761754199, 1761754199),
(38468, 'Songofsongs 4:2', 'Songofsongs', 4, 2, 'ستا غاښونه د سپينو ګډو په شان دينه، چې تازه ترې نه وړۍ اخوا شوې وينه، او تازه لمبولے شوے وينه. هر يو غاښ دې د بل سره جوړه دېنه، يو هم کنډم شوے نۀ دېنه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs4_verse_2.mp3', '', 1761754199, 1761754199),
(38469, 'Songofsongs 4:3', 'Songofsongs', 4, 3, 'شونډې دې تکې سرې دينه، خولۀ دې ډېره ښُکلې ښکارينه. ستا اننګى د نقاب شاته لکه د ګلابى انار ځليږينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs4_verse_3.mp3', '', 1761754199, 1761754199),
(38470, 'Songofsongs 4:4', 'Songofsongs', 4, 4, 'ستا غړۍ دومره ښائسته ده لکه د داؤد د ښار مناره، چې د زرګونو بهادرانو په ډالونو باندې شوې وى سينګاره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs4_verse_4.mp3', '', 1761754199, 1761754199),
(38471, 'Songofsongs 4:5', 'Songofsongs', 4, 5, 'ستا سينې لکه د هوسو د جوړه بچو په شان دينه، چې د لاله په ګلونو کښې څريږينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs4_verse_5.mp3', '', 1761754199, 1761754199),
(38472, 'Songofsongs 4:6', 'Songofsongs', 4, 6, 'د دې نه وړاندې چې د سحر باد ولګيږينه او د شپې تيارۀ چې په ختمېدو شينه، زۀ به د مُر غر ته ورمنډه کړمه او د لوبانو غونډو ته به لاړه شمه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs4_verse_6.mp3', '', 1761754199, 1761754199),
(38473, 'Songofsongs 4:7', 'Songofsongs', 4, 7, 'زما محبوبې، ستا ښائست کامِل دېنه، په تا کښې هيڅ عېب نشته دېنه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs4_verse_7.mp3', '', 1761754199, 1761754199),
(38474, 'Songofsongs 4:8', 'Songofsongs', 4, 8, 'زما ناوې، د لبنان نه ما سره راشه، د لبنان نه ما سره راشه. د امانه د غرۀ د څوکو نه راکوزه شه، د حرمون او د سنير د څوکو نه ما سره راکوزه شه، د زمرو د غارونو او د پړانګانو د غونډو نه راکوزه شه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs4_verse_8.mp3', '', 1761754199, 1761754199),
(38475, 'Songofsongs 4:9', 'Songofsongs', 4, 9, 'اے زما دُنيا، اے زما ناوې، زما نه دې زړۀ وړے دېنه، د سترګو په يوه اِشاره دې ما نه زړګے وړے دېنه، او د اميل يو غمى دې ما نه زړګے وړے دېنه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs4_verse_9.mp3', '', 1761754199, 1761754199),
(38476, 'Songofsongs 4:10', 'Songofsongs', 4, 10, 'زما دُنيا، زما ناوې زۀ ستا په مينه کښې څومره خوشحاله يمه، د ميو نه څومره خوشحالونکى ده ستا مينه، او ستا خوشبو د هرې مصالحې نه څومره ښۀ ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs4_verse_10.mp3', '', 1761754199, 1761754199),
(38477, 'Songofsongs 4:11', 'Songofsongs', 4, 11, 'زما ناوې، ستا د شونډو نه د شاتو د ګبين په شان خوږوالے راڅاڅيږينه، ستا د ژبې لاندې شات او پئ پراتۀ دينه، ستا د جامو نه لکه د لبنان د دِيار په شان خوشبو راځينه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs4_verse_11.mp3', '', 1761754199, 1761754199),
(38478, 'Songofsongs 4:12', 'Songofsongs', 4, 12, 'اے زما محبوبې، تۀ زما بنده باغيچه ينه، تۀ زما دُنيا ينه، او زما ناوې ينه، زما پټ باغ، زما پټه چينه ينه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs4_verse_12.mp3', '', 1761754199, 1761754199),
(38479, 'Songofsongs 4:13', 'Songofsongs', 4, 13, 'تۀ لکه د انارو باغيچه ينه، د مزېدارو مېوو نه ډکه ينه، او خوشبو دې لکه د مشکو او عنبرو په شان ده نه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs4_verse_13.mp3', '', 1761754199, 1761754199),
(38480, 'Songofsongs 4:14', 'Songofsongs', 4, 14, 'چرته چې د مشکو، زعفرانو، دارچينو او هر قسمه مصالحو بوټى پېدا کيږينه، او عُود، مُر او لوبانو خوشبوداره عطر پېدا کيږينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs4_verse_14.mp3', '', 1761754199, 1761754199),
(38481, 'Songofsongs 4:15', 'Songofsongs', 4, 15, 'تۀ د باغ چينه ينه، تۀ د تازه اوبو کوهے ينه چې د لبنان د غرونو نه رابهيږينه. محبوبه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs4_verse_15.mp3', '', 1761754199, 1761754199),
(38482, 'Songofsongs 4:16', 'Songofsongs', 4, 16, 'اے د شمال باده، راوالوځه، اے د جنوب باده راشه، زما په باغ باندې راوالوځه او د هغۀ خوشبو هرې خوا ته خوره کړه. زما جانانه خپل باغ ته راشه، او د هغې ښُکلې مېوې وخوره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs4_verse_16.mp3', '', 1761754199, 1761754199),
(38483, 'Job 42:1', 'Job', 42, 1, 'بيا ايُوب مالِک خُدائ له جواب ورکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job42_verse_1.mp3', '', 1761754199, 1761754199),
(38484, 'Job 42:2', 'Job', 42, 2, '”ما ته پته ده چې تۀ هر څۀ کولے شې، او تا د خپل کار نه هيڅ څوک نۀ شى ايسارولے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job42_verse_2.mp3', '', 1761754199, 1761754199),
(38485, 'Job 42:3', 'Job', 42, 3, 'تا وفرمائيل چې، ”هغه څوک دے چې زما په حِکمت باندې د ناپوهۍ سره شک کوى؟“ هغه زۀ يم، ما د داسې څيزونو خبره کوله چې ما ته يې هيڅ پته نۀ وه، او هغه خبرې زما دپاره ډېرې عجيبه او لوئې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job42_verse_3.mp3', '', 1761754199, 1761754199),
(38486, 'Job 42:4', 'Job', 42, 4, 'تا وفرمائيل چې، ”ما ته غوږ ونيسه او زۀ به وايم، زۀ به تپوس کوم او تۀ به ما له جواب راکوې.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job42_verse_4.mp3', '', 1761754199, 1761754199),
(38487, 'Job 42:5', 'Job', 42, 5, 'ما مخکښې صرف ستا په حقله اورېدلى دى، خو اوس مې په خپلو سترګو وليدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job42_verse_5.mp3', '', 1761754199, 1761754199),
(38488, 'Job 42:6', 'Job', 42, 6, 'نو ما چې څۀ وئيلى دى نو په هغې شرمنده يم، او په خاورو او ايرو کښې توبه وباسم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job42_verse_6.mp3', '', 1761754199, 1761754199),
(38489, 'Job 42:7', 'Job', 42, 7, 'کله چې مالِک خُدائ د ايُوب سره دا خبرې وکړې، نو مالِک خُدائ تيمانى اليفز ته وفرمائيل، ”زۀ تا او ستا دوو ملګرو ته سخت غصه يم، ځکه چې تاسو زما هغه خبره نۀ ده کړې چې کومه صحيح ده، لکه څنګه چې زما خِدمت کوونکى ايُوب کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job42_verse_7.mp3', '', 1761754199, 1761754199),
(38490, 'Job 42:8', 'Job', 42, 8, 'نو په دې وجه اوس اووۀ غوَيى او اووۀ ګډان بوځه او زما خِدمت کوونکى ايُوب له ورشه او د خپل ځان دپاره دا د سوزېدونکې نذرانې په توګه پېش کړه، نو زما خِدمت کوونکے ايُوب به ستا دپاره دُعا وکړى، ځکه چې زۀ به د هغۀ دُعا قبلوم او ستاسو د کم عقلتوب په مطابق کار به درسره نۀ کوم، ځکه چې تاسو زما هغه خبره نۀ ده کړې چې کومه صحيح ده، لکه څنګه چې زما خِدمت کوونکى ايُوب کړې ده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job42_verse_8.mp3', '', 1761754199, 1761754199),
(38491, 'Job 42:9', 'Job', 42, 9, 'نو تيمانى اليفز، شوحى بِلداد او نعماتى ضوفر لاړل او چې مالِک خُدائ څنګه فرمائيلى وُو هم هغه شان يې وکړل، او مالِک خُدائ د ايُوب دُعا قبوله کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job42_verse_9.mp3', '', 1761754199, 1761754199),
(38492, 'Job 42:10', 'Job', 42, 10, 'نو کله چې ايُوب د خپلو ملګرو دپاره دُعا وکړه نو خُدائ پاک هغۀ له بيا برکت ورکړو، او چې ايُوب مخکښې څۀ لرل نو مالِک خُدائ هغۀ له د هغې يو په دوه نور هم زيات ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job42_verse_10.mp3', '', 1761754199, 1761754199),
(38493, 'Job 42:11', 'Job', 42, 11, 'نو هلته هغۀ له د هغۀ ټول وروڼه خوېندې او ټول پخوانى خپل پردى راغلل او هغوئ د هغۀ په کور کښې روټۍ وخوړه. او هغوئ ورته مينه ښکاره کړه او د هغه تکليفونو په وجه يې هغۀ له تسلى ورکړه چې مالِک خُدائ په هغۀ راوستى وُو. او هغوئ هر يو هغۀ له لږې پېسې او يوه د سرو زرو ګوتمه ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job42_verse_11.mp3', '', 1761754199, 1761754199),
(38494, 'Job 42:12', 'Job', 42, 12, 'نو مالِک خُدائ د ايُوب وروستنے عُمر د اول عُمر نه زيات برکتناک کړو، او د هغۀ څوارلس زره ګډې، شپږ زره اوښان، دوه زره غوَيى او يو زر خرۀ وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job42_verse_12.mp3', '', 1761754199, 1761754199),
(38495, 'Job 42:13', 'Job', 42, 13, 'د هغۀ اووۀ زامن او درې لوڼه هم وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job42_verse_13.mp3', '', 1761754199, 1761754199),
(38496, 'Job 42:14', 'Job', 42, 14, 'هغۀ په وړومبۍ لور باندې يميمه، په دوېمه قصياه او په درېمه باندې قرن‌هپوک نوم کېښودو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job42_verse_14.mp3', '', 1761754199, 1761754199),
(38497, 'Job 42:15', 'Job', 42, 15, 'او په هغه ټول مُلک کښې د ايُوب د لوڼو په شان ښائسته ښځې نۀ وې، خپل پلار هغوئ له د دوئ د وروڼو په شان ميراث ورکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job42_verse_15.mp3', '', 1761754199, 1761754199),
(38498, 'Job 42:16', 'Job', 42, 16, 'ايُوب د دې نه پس يو سل او څلوېښت کاله ژوندے وو او د څلورم نسل پورې خپل بچى او نمسى يې وليدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job42_verse_16.mp3', '', 1761754199, 1761754199),
(38499, 'Job 42:17', 'Job', 42, 17, 'نو بيا ايُوب په پوخ عُمر کښې مړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job42_verse_17.mp3', '', 1761754199, 1761754199),
(38500, 'Genesis 47:1', 'Genesis', 47, 1, 'نو یوسف لاړ او فرعون ته یې وویل: «زما پلار او زما ورونه د خپلو رمو، پادو او خپلو ټولو شیانو سره چې درلودل یې د کنعان څخه راغلي دي او اوس د جوشن په سیمه کې دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_1.mp3', '', 1761754199, 1761754199),
(38501, 'Genesis 47:2', 'Genesis', 47, 2, 'هغه د خپلو ورونو څخه پنځه تنه غوره کړل او فرعون ته یې وروپېژندل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_2.mp3', '', 1761754199, 1761754199),
(38502, 'Genesis 47:3', 'Genesis', 47, 3, 'فرعون د هغوی څخه پوښتنه وکړه: «تاسو څه کار کوئ؟» هغوی ځواب ورکړ: «مونږ د خپلو نیکونو په شان شپانه یو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_3.mp3', '', 1761754199, 1761754199),
(38503, 'Genesis 47:4', 'Genesis', 47, 4, 'مونږ راغلي یو چې د یو څه مودې دپاره په دې وطن کې واوسېږو، ځکه چې د کنعان په خاوره کې ډېره سخته قحطي ده او هلته زمونږ د رمو دپاره څړځای نشته. نو اوس مونږ ته اجازه راکړئ چې د جوشن په سیمه کې واوسېږو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_4.mp3', '', 1761754199, 1761754199),
(38504, 'Genesis 47:5', 'Genesis', 47, 5, 'فرعون یوسف ته وویل: «اوس چې ستا پلار او ورونه تاته راغلي دي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_5.mp3', '', 1761754199, 1761754199),
(38505, 'Genesis 47:6', 'Genesis', 47, 6, 'د مصر ځمکه ستا په واک کې ده. پرېږده چې هغوی د جوشن په سیمه کې چې د دې هېواد تر ټولو ښه ځمکه ده، واوسیږي. همدارنګه زه غواړم چې ستاسو ډېر ښه شپانه دې زما پسونه او وزې وساتي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_6.mp3', '', 1761754199, 1761754199),
(38506, 'Genesis 47:7', 'Genesis', 47, 7, 'بیا یوسف خپل پلار یعقوب راوست او فرعون ته یې وروپېژانده. یعقوب فرعون ته برکت ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_7.mp3', '', 1761754199, 1761754199),
(38507, 'Genesis 47:8', 'Genesis', 47, 8, 'فرعون د یعقوب څخه پوښتنه وکړه: «ستا عمر څومره دی؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_8.mp3', '', 1761754199, 1761754199),
(38508, 'Genesis 47:9', 'Genesis', 47, 9, 'یعقوب ځواب ورکړ: «زما د عمر یوسلو دېرش کاله شوي دي او د یو ځای څخه مې بل ځای ته کډه کړې ده. زما پلرونو او نیکونو هم د یو ځای څخه بل ځای ته کډه کړې ده. خو هغوی اوږد عمر درلود او د هغوی ژوند زما د ژوند په شان سخت نه ؤ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_9.mp3', '', 1761754199, 1761754199),
(38509, 'Genesis 47:10', 'Genesis', 47, 10, 'یعقوب یوځل بیا فرعون ته برکت ورکړ او د هغه د حضور څخه لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_10.mp3', '', 1761754199, 1761754199),
(38510, 'Genesis 47:11', 'Genesis', 47, 11, 'نو یوسف د فرعون د امر سره سم خپل پلار او ورونو ته په مصر کې ډېر ښه ځای چې د رعمسیس ښار ته نژدې ؤ، ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis47_verse_11.mp3', '', 1761754199, 1761754199);